/**
 * AudioClip (FSB5) and VideoClip helpers for the Unity AssetBundle viewer.
 *
 * Audio: PCM8/16/float, IMA/FADPCM/GCADPCM to WAV via unity-asset-reader-audio;
 *        Vorbis to Ogg remux (@tootallnate/fsb5 + setup CRC table) then
 *        decode to WAV with @wasm-audio-decoders/ogg-vorbis for iOS Safari.
 * Video: slice raw bytes from the .resource stream; sniff container MIME.
 */

import {
  parseFsb5,
  isFsb5,
  decodeSampleToBlob,
  loadFmodVorbisSetupPackets,
  SOUND_FORMAT,
  SOUND_FORMAT_NAMES,
} from "@tootallnate/fsb5";
import { fsb5ToWav, readFsb5, Fsb5Codec } from "unity-asset-reader-audio";
import { OggVorbisDecoder } from "@wasm-audio-decoders/ogg-vorbis";

let vorbisLibPromise = null;
let decoderPromise = null;

function getVorbisLib() {
  if (!vorbisLibPromise) {
    vorbisLibPromise = (async () => {
      // Bundled app.js is served next to assets/
      const url = new URL("./assets/fmod_vorbis_setup_packets.bin", import.meta.url).href;
      const r = await fetch(url);
      if (!r.ok) {
        throw new Error(`Vorbis セットアップ表の読み込みに失敗 (${r.status})`);
      }
      return loadFmodVorbisSetupPackets(new Uint8Array(await r.arrayBuffer()));
    })();
  }
  return vorbisLibPromise;
}

/** Optional: preload setup table bytes (used by Node unit tests). */
export function preloadVorbisSetup(bytes) {
  vorbisLibPromise = Promise.resolve(
    loadFmodVorbisSetupPackets(bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes))
  );
}

function getVorbisDecoder() {
  if (!decoderPromise) {
    const dec = new OggVorbisDecoder();
    decoderPromise = dec.ready.then(() => dec);
  }
  return decoderPromise;
}

/** Interleaved Float32 channelData → 16-bit PCM WAV bytes. */
export function floatChannelsToWav(channelData, sampleRate) {
  const channels = channelData.length;
  const frames = channelData[0]?.length || 0;
  const dataBytes = frames * channels * 2;
  const out = new Uint8Array(44 + dataBytes);
  const dv = new DataView(out.buffer);
  const enc = new TextEncoder();
  out.set(enc.encode("RIFF"), 0);
  dv.setUint32(4, 36 + dataBytes, true);
  out.set(enc.encode("WAVE"), 8);
  out.set(enc.encode("fmt "), 12);
  dv.setUint32(16, 16, true);
  dv.setUint16(20, 1, true);
  dv.setUint16(22, channels, true);
  dv.setUint32(24, sampleRate, true);
  dv.setUint32(28, sampleRate * channels * 2, true);
  dv.setUint16(32, channels * 2, true);
  dv.setUint16(34, 16, true);
  out.set(enc.encode("data"), 36);
  dv.setUint32(40, dataBytes, true);
  let o = 44;
  for (let i = 0; i < frames; i++) {
    for (let c = 0; c < channels; c++) {
      const s = Math.max(-1, Math.min(1, channelData[c][i]));
      dv.setInt16(o, (s * 32767) | 0, true);
      o += 2;
    }
  }
  return out;
}

function codecLabel(mode) {
  return SOUND_FORMAT_NAMES[mode] || Fsb5CodecName(mode) || `codec_${mode}`;
}

function Fsb5CodecName(mode) {
  for (const [k, v] of Object.entries(Fsb5Codec)) {
    if (v === mode) return k;
  }
  return null;
}

/**
 * @typedef {object} DecodedAudio
 * @property {Uint8Array} playBytes  bytes for <audio> (WAV preferred)
 * @property {string} playMime
 * @property {Uint8Array} downloadBytes
 * @property {string} downloadExt  'wav' | 'ogg' | 'mp3' | ...
 * @property {string} downloadMime
 * @property {string} codecName
 * @property {number} [duration] seconds
 * @property {number} [channels]
 * @property {number} [frequency]
 * @property {Uint8Array} [oggBytes] original remuxed Ogg when Vorbis
 */

/**
 * Decode AudioClip.audioData (usually FSB5) into playable + downloadable bytes.
 * @param {Uint8Array} audioData
 * @param {{ length?: number, channels?: number, frequency?: number, compressionFormat?: number, name?: string }} meta
 * @returns {Promise<DecodedAudio>}
 */
export async function decodeAudioClipData(audioData, meta = {}) {
  if (!audioData || !audioData.length) {
    throw new Error("音声データが空です");
  }

  // Non-FSB5: legacy inline Ogg / MP3 / WAV
  if (!isFsb5(audioData) && !looksLikeFsb5(audioData)) {
    return decodeRawAudioContainer(audioData, meta);
  }

  let mode;
  let sampleMeta = {
    channels: meta.channels,
    frequency: meta.frequency,
    duration: meta.length,
  };

  try {
    const bank = readFsb5(audioData);
    mode = bank.codec;
    const s0 = bank.samples[0];
    if (s0) {
      sampleMeta = {
        channels: s0.channels,
        frequency: s0.frequency,
        duration:
          s0.frequency > 0 ? s0.sampleCount / s0.frequency : meta.length,
      };
    }
  } catch {
    // Fall through to tootallnate parse for Vorbis-only edge cases
    try {
      const fsb = parseFsb5(audioData);
      mode = fsb.header.mode;
      const s0 = fsb.samples[0];
      sampleMeta = {
        channels: s0.channels,
        frequency: s0.frequency,
        duration: s0.frequency > 0 ? s0.numSamples / s0.frequency : meta.length,
      };
    } catch (e) {
      throw new Error(`FSB5 を解析できません: ${e.message || e}`);
    }
  }

  if (mode === Fsb5Codec.VORBIS || mode === SOUND_FORMAT.VORBIS) {
    return decodeVorbisFsb(audioData, sampleMeta);
  }

  // PCM / ADPCM / FADPCM / GCADPCM via unity-asset-reader-audio
  try {
    const wav = fsb5ToWav(audioData);
    return {
      playBytes: wav,
      playMime: "audio/wav",
      downloadBytes: wav,
      downloadExt: "wav",
      downloadMime: "audio/wav",
      codecName: codecLabel(mode),
      duration: sampleMeta.duration,
      channels: sampleMeta.channels,
      frequency: sampleMeta.frequency,
    };
  } catch (e) {
    // Last resort: tootallnate PCM/IMA path
    try {
      const lib = await getVorbisLib();
      const fsb = parseFsb5(audioData);
      const result = await decodeSampleToBlob(fsb.samples[0], fsb.header.mode, lib);
      const bytes = new Uint8Array(await result.blob.arrayBuffer());
      if (result.extension === "ogg") {
        return finalizeVorbis(bytes, sampleMeta);
      }
      return {
        playBytes: bytes,
        playMime: "audio/wav",
        downloadBytes: bytes,
        downloadExt: "wav",
        downloadMime: "audio/wav",
        codecName: codecLabel(fsb.header.mode),
        duration: sampleMeta.duration,
        channels: sampleMeta.channels,
        frequency: sampleMeta.frequency,
      };
    } catch (e2) {
      const name = codecLabel(mode);
      throw new Error(
        `未対応の音声コーデックです（${name}）。ダウンロードもできません。`
      );
    }
  }
}

function looksLikeFsb5(u8) {
  return (
    u8.length >= 4 &&
    u8[0] === 0x46 &&
    u8[1] === 0x53 &&
    u8[2] === 0x42 &&
    u8[3] === 0x35
  );
}

async function decodeVorbisFsb(audioData, sampleMeta) {
  const lib = await getVorbisLib();
  let fsb;
  try {
    fsb = parseFsb5(audioData);
  } catch (e) {
    throw new Error(`Vorbis FSB5 を解析できません: ${e.message || e}`);
  }
  if (fsb.header.mode !== SOUND_FORMAT.VORBIS) {
    throw new Error("FSB5 モードが Vorbis ではありません");
  }
  let oggBytes;
  try {
    const result = await decodeSampleToBlob(fsb.samples[0], SOUND_FORMAT.VORBIS, lib);
    oggBytes = new Uint8Array(await result.blob.arrayBuffer());
  } catch (e) {
    throw new Error(
      `Vorbis の Ogg 再構築に失敗しました（未知のセットアップ CRC の可能性）: ${e.message || e}`
    );
  }
  return finalizeVorbis(oggBytes, {
    channels: fsb.samples[0].channels,
    frequency: fsb.samples[0].frequency,
    duration:
      fsb.samples[0].frequency > 0
        ? fsb.samples[0].numSamples / fsb.samples[0].frequency
        : sampleMeta.duration,
  });
}

async function finalizeVorbis(oggBytes, sampleMeta) {
  // Always decode to WAV for reliable playback (esp. iOS Safari).
  const dec = await getVorbisDecoder();
  await dec.reset();
  const decoded = await dec.decodeFile(oggBytes);
  if (!decoded.samplesDecoded || !decoded.channelData?.length) {
    const err = decoded.errors?.[0];
    throw new Error(
      `Vorbis のデコードに失敗しました${err ? `: ${err.message}` : ""}`
    );
  }
  const wav = floatChannelsToWav(decoded.channelData, decoded.sampleRate);
  const duration =
    decoded.sampleRate > 0
      ? decoded.samplesDecoded / decoded.sampleRate
      : sampleMeta.duration;
  return {
    playBytes: wav,
    playMime: "audio/wav",
    downloadBytes: wav,
    downloadExt: "wav",
    downloadMime: "audio/wav",
    codecName: "VORBIS",
    duration,
    channels: decoded.channelData.length,
    frequency: decoded.sampleRate,
    oggBytes,
  };
}

function decodeRawAudioContainer(audioData, meta) {
  const info = sniffAudio(audioData);
  if (!info) {
    throw new Error("未対応の音声コンテナです（FSB5 / Ogg / MP3 / WAV 以外）");
  }
  return {
    playBytes: audioData,
    playMime: info.mime,
    downloadBytes: audioData,
    downloadExt: info.ext,
    downloadMime: info.mime,
    codecName: info.label,
    duration: meta.length,
    channels: meta.channels,
    frequency: meta.frequency,
  };
}

function sniffAudio(u8) {
  if (u8.length >= 4 && u8[0] === 0x4f && u8[1] === 0x67 && u8[2] === 0x67 && u8[3] === 0x53) {
    return { mime: "audio/ogg", ext: "ogg", label: "Ogg" };
  }
  if (u8.length >= 3 && u8[0] === 0x49 && u8[1] === 0x44 && u8[2] === 0x33) {
    return { mime: "audio/mpeg", ext: "mp3", label: "MP3" };
  }
  if (u8.length >= 2 && u8[0] === 0xff && (u8[1] & 0xe0) === 0xe0) {
    return { mime: "audio/mpeg", ext: "mp3", label: "MP3" };
  }
  if (
    u8.length >= 12 &&
    u8[0] === 0x52 &&
    u8[1] === 0x49 &&
    u8[2] === 0x46 &&
    u8[3] === 0x46 &&
    u8[8] === 0x57 &&
    u8[9] === 0x41 &&
    u8[10] === 0x56 &&
    u8[11] === 0x45
  ) {
    return { mime: "audio/wav", ext: "wav", label: "WAV" };
  }
  return null;
}

/**
 * @typedef {object} DecodedVideo
 * @property {Uint8Array} bytes
 * @property {string} mime
 * @property {string} ext
 * @property {boolean} playable  browser can likely play it
 * @property {string} [unplayableReason]
 * @property {number} [width]
 * @property {number} [height]
 * @property {number} [duration] seconds if known
 * @property {string} [originalPath]
 */

/**
 * Prepare VideoClip.videoData for <video> + download.
 * @param {Uint8Array} videoData
 * @param {{ width?: number, height?: number, frameRate?: number, frameCount?: bigint|number, originalPath?: string }} meta
 */
export function prepareVideoClipData(videoData, meta = {}) {
  if (!videoData || !videoData.length) {
    throw new Error("動画データが空です");
  }
  const info = sniffVideo(videoData, meta.originalPath);
  let duration;
  const fc = meta.frameCount != null ? Number(meta.frameCount) : NaN;
  if (meta.frameRate > 0 && Number.isFinite(fc) && fc > 0) {
    duration = fc / meta.frameRate;
  }
  return {
    bytes: videoData,
    mime: info.mime,
    ext: info.ext,
    playable: info.playable,
    unplayableReason: info.playable
      ? undefined
      : `この動画形式（${info.label}）はブラウザで再生できない可能性があります。ダウンロードして別アプリで開いてください。`,
    width: meta.width,
    height: meta.height,
    duration,
    originalPath: meta.originalPath,
    label: info.label,
  };
}

function sniffVideo(u8, originalPath = "") {
  const path = String(originalPath || "").toLowerCase();
  const extFromPath = path.includes(".") ? path.slice(path.lastIndexOf(".") + 1) : "";

  // ISO BMFF: ....ftyp
  if (u8.length >= 8) {
    const brand = String.fromCharCode(u8[4], u8[5], u8[6], u8[7]);
    if (brand === "ftyp") {
      const major = String.fromCharCode(u8[8], u8[9], u8[10], u8[11] || 0);
      if (major.startsWith("qt") || extFromPath === "mov") {
        return { mime: "video/quicktime", ext: "mov", label: "QuickTime / MOV", playable: true };
      }
      if (extFromPath === "m4v" || major.includes("M4V") || major === "M4V ") {
        return { mime: "video/x-m4v", ext: "m4v", label: "M4V", playable: true };
      }
      return { mime: "video/mp4", ext: "mp4", label: "MP4", playable: true };
    }
  }
  // WebM / Matroska EBML
  if (u8.length >= 4 && u8[0] === 0x1a && u8[1] === 0x45 && u8[2] === 0xdf && u8[3] === 0xa3) {
    const isWebm = extFromPath === "webm" || indexOfAscii(u8, "webm", 0, 64) >= 0;
    if (isWebm) return { mime: "video/webm", ext: "webm", label: "WebM", playable: true };
    return { mime: "video/x-matroska", ext: "mkv", label: "Matroska", playable: false };
  }
  // Ogg Theora (legacy MovieTexture)
  if (u8.length >= 4 && u8[0] === 0x4f && u8[1] === 0x67 && u8[2] === 0x67 && u8[3] === 0x53) {
    return { mime: "video/ogg", ext: "ogv", label: "Ogg Theora", playable: true };
  }
  // Extension fallback
  const map = {
    mp4: { mime: "video/mp4", ext: "mp4", label: "MP4", playable: true },
    m4v: { mime: "video/x-m4v", ext: "m4v", label: "M4V", playable: true },
    mov: { mime: "video/quicktime", ext: "mov", label: "MOV", playable: true },
    webm: { mime: "video/webm", ext: "webm", label: "WebM", playable: true },
    ogv: { mime: "video/ogg", ext: "ogv", label: "Ogg", playable: true },
    avi: { mime: "video/x-msvideo", ext: "avi", label: "AVI", playable: false },
  };
  if (extFromPath && map[extFromPath]) return map[extFromPath];
  return {
    mime: "application/octet-stream",
    ext: extFromPath || "bin",
    label: extFromPath ? extFromPath.toUpperCase() : "不明",
    playable: false,
  };
}

function indexOfAscii(u8, ascii, start, end) {
  const enc = new TextEncoder().encode(ascii);
  const last = Math.min(u8.length - enc.length, end);
  outer: for (let i = start; i <= last; i++) {
    for (let j = 0; j < enc.length; j++) {
      if (u8[i + j] !== enc[j]) continue outer;
    }
    return i;
  }
  return -1;
}

export function formatDuration(seconds) {
  if (seconds == null || !Number.isFinite(seconds) || seconds < 0) return "";
  const s = Math.round(seconds);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${m}:${String(r).padStart(2, "0")}`;
}

/** Preload Vorbis setup table + WASM decoder (call during init). */
export async function initMedia(setupBytes) {
  if (setupBytes) preloadVorbisSetup(setupBytes);
  await getVorbisLib();
  await getVorbisDecoder();
}
