import { load } from "unity-asset-reader";
import {
  initTexture,
  isImage,
  imageInfo,
  decodeImage,
  encodePng,
} from "unity-asset-reader-texture";
import { zipSync, unzipSync } from "fflate";
import {
  decodeAudioClipData,
  prepareVideoClipData,
  formatDuration,
  initMedia,
} from "./media.js";

const WASM_PATH = new URL("./wasm/", import.meta.url).href;

const UNITY_MAGICS = ["UnityFS", "UnityWeb", "UnityRaw"];

/** Strip any bytes before UnityFS / UnityWeb / UnityRaw magic. */
function normalizeBundleBytes(bytes) {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  for (const m of UNITY_MAGICS) {
    const enc = new TextEncoder().encode(m);
    outer: for (let i = 0; i <= Math.min(64, u8.length - enc.length); i++) {
      for (let j = 0; j < enc.length; j++) {
        if (u8[i + j] !== enc[j]) continue outer;
      }
      if (i === 0) return u8;
      return u8.subarray(i);
    }
  }
  return u8;
}

function looksLikeUnityBundle(bytes) {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  if (u8.length < 16) return false;
  for (const m of UNITY_MAGICS) {
    const enc = new TextEncoder().encode(m);
    outer: for (let i = 0; i <= Math.min(64, u8.length - enc.length); i++) {
      for (let j = 0; j < enc.length; j++) {
        if (u8[i + j] !== enc[j]) continue outer;
      }
      return true;
    }
  }
  return false;
}

function isZipBytes(bytes) {
  return bytes.length >= 4 && bytes[0] === 0x50 && bytes[1] === 0x4b;
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function safeFilename(name) {
  return (
    String(name || "asset")
      .replace(/[\\/:*?"<>|]+/g, "_")
      .replace(/^\.+/, "_")
      .slice(0, 120) || "asset"
  );
}

function basename(path) {
  const s = String(path || "").replace(/\\/g, "/");
  const i = s.lastIndexOf("/");
  return i >= 0 ? s.slice(i + 1) : s;
}

function stem(name) {
  const b = basename(name);
  const i = b.lastIndexOf(".");
  return i > 0 ? b.slice(0, i) : b;
}

function yieldToUi() {
  return new Promise((r) => setTimeout(r, 0));
}

const state = {
  ready: false,
  busy: false,
  // kind: 'image' | 'audio' | 'video'
  items: [],
  errors: [],
  label: "",
};

const $ = (sel) => document.querySelector(sel);

function setStatus(msg, kind = "") {
  const el = $("#status");
  el.textContent = msg || "";
  el.dataset.kind = kind;
}

function showProgress(show, label = "") {
  const wrap = $("#progress-wrap");
  wrap.hidden = !show;
  if (label) $("#progress-label").textContent = label;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function kindLabel(kind) {
  if (kind === "audio") return "音声";
  if (kind === "video") return "動画";
  return "画像";
}

function cardThumbHtml(item) {
  if (item.kind === "image") {
    return `<img src="${item.thumbUrl}" alt="${escapeHtml(item.name)}" loading="lazy" />`;
  }
  if (item.kind === "audio") {
    const dur = formatDuration(item.duration);
    return `<div class="media-thumb audio" aria-hidden="true">
      <span class="media-icon">♪</span>
      <span class="media-tag">AUDIO${dur ? " · " + dur : ""}</span>
    </div>`;
  }
  const dur = formatDuration(item.duration);
  const wh =
    item.width && item.height ? `${item.width}×${item.height}` : "VIDEO";
  return `<div class="media-thumb video" aria-hidden="true">
    <span class="media-icon">▶</span>
    <span class="media-tag">${escapeHtml(wh)}${dur ? " · " + dur : ""}</span>
  </div>`;
}

function cardSubHtml(item) {
  if (item.kind === "image") {
    return `${item.width}×${item.height} · ${escapeHtml(item.formatName)} · ${item.type}`;
  }
  if (item.kind === "audio") {
    const parts = [item.codecName || "Audio", item.type];
    if (item.channels) parts.unshift(`${item.channels}ch`);
    if (item.frequency) parts.unshift(`${item.frequency} Hz`);
    const dur = formatDuration(item.duration);
    if (dur) parts.push(dur);
    return escapeHtml(parts.join(" · "));
  }
  const parts = [item.containerLabel || item.ext || "Video", item.type];
  if (item.width && item.height) parts.unshift(`${item.width}×${item.height}`);
  const dur = formatDuration(item.duration);
  if (dur) parts.push(dur);
  return escapeHtml(parts.join(" · "));
}

function renderGrid() {
  const grid = $("#grid");
  grid.innerHTML = "";
  $("#actions").hidden = state.items.length === 0;
  $("#empty").hidden = state.items.length > 0 || state.errors.length > 0;

  const errorsEl = $("#errors");
  if (state.errors.length) {
    errorsEl.hidden = false;
    errorsEl.innerHTML =
      `<div class="errors-title">スキップ / エラー (${state.errors.length})</div>` +
      state.errors
        .map(
          (e) =>
            `<div class="error-row"><strong>${escapeHtml(e.sourceName)}</strong>: ${escapeHtml(e.message)}</div>`
        )
        .join("");
  } else {
    errorsEl.hidden = true;
    errorsEl.innerHTML = "";
  }

  const groups = new Map();
  for (const [i, item] of state.items.entries()) {
    const key = item.sourceName || "(unknown)";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({ item, index: i });
  }

  for (const [source, entries] of groups) {
    const section = document.createElement("section");
    section.className = "group";
    const counts = { image: 0, audio: 0, video: 0 };
    for (const { item } of entries) counts[item.kind] = (counts[item.kind] || 0) + 1;
    const countParts = [];
    if (counts.image) countParts.push(`画像 ${counts.image}`);
    if (counts.audio) countParts.push(`音声 ${counts.audio}`);
    if (counts.video) countParts.push(`動画 ${counts.video}`);
    section.innerHTML = `<h3 class="group-title">${escapeHtml(source)} <span class="group-count">${countParts.join(" · ") || entries.length}</span></h3>`;
    const cards = document.createElement("div");
    cards.className = "group-grid";
    for (const { item, index } of entries) {
      const card = document.createElement("button");
      card.type = "button";
      card.className = `card kind-${item.kind}`;
      card.innerHTML = `
        ${cardThumbHtml(item)}
        <div class="meta">
          <div class="name">${escapeHtml(item.name)}</div>
          <div class="sub">${cardSubHtml(item)}</div>
        </div>
      `;
      card.addEventListener("click", () => openLightbox(index));
      cards.appendChild(card);
    }
    section.appendChild(cards);
    grid.appendChild(section);
  }
}

function stopMedia() {
  const audio = $("#lb-audio");
  const video = $("#lb-video");
  try {
    audio.pause();
    audio.removeAttribute("src");
    audio.load();
  } catch {}
  try {
    video.pause();
    video.removeAttribute("src");
    video.load();
  } catch {}
}

function openLightbox(index) {
  const item = state.items[index];
  if (!item) return;
  stopMedia();
  const lb = $("#lightbox");
  const img = $("#lb-img");
  const audio = $("#lb-audio");
  const video = $("#lb-video");
  const warn = $("#lb-warn");
  const mediaWrap = $("#lb-media-wrap");

  img.hidden = true;
  audio.hidden = true;
  video.hidden = true;
  warn.hidden = true;
  mediaWrap.classList.remove("is-audio", "is-video", "is-image");

  $("#lb-title").textContent = item.name;

  if (item.kind === "image") {
    mediaWrap.classList.add("is-image");
    img.hidden = false;
    img.src = item.fullUrl;
    $("#lb-info").textContent = `${item.sourceName} · ${item.width}×${item.height} · ${item.formatName} · ${item.type}`;
    $("#lb-download").textContent = "PNG保存";
  } else if (item.kind === "audio") {
    mediaWrap.classList.add("is-audio");
    audio.hidden = false;
    audio.src = item.playUrl;
    const dur = formatDuration(item.duration);
    $("#lb-info").textContent = [
      item.sourceName,
      item.codecName,
      item.channels ? `${item.channels}ch` : null,
      item.frequency ? `${item.frequency} Hz` : null,
      dur || null,
      item.type,
    ]
      .filter(Boolean)
      .join(" · ");
    $("#lb-download").textContent = `${(item.downloadExt || "wav").toUpperCase()}保存`;
  } else {
    mediaWrap.classList.add("is-video");
    video.hidden = false;
    if (item.playable) {
      video.src = item.playUrl;
    } else {
      warn.hidden = false;
      warn.textContent =
        item.unplayableReason ||
        "この形式はブラウザで再生できません。ダウンロードしてください。";
    }
    const dur = formatDuration(item.duration);
    $("#lb-info").textContent = [
      item.sourceName,
      item.width && item.height ? `${item.width}×${item.height}` : null,
      item.containerLabel || item.ext,
      dur || null,
      item.type,
    ]
      .filter(Boolean)
      .join(" · ");
    $("#lb-download").textContent = `${(item.ext || "bin").toUpperCase()}保存`;
  }

  lb.hidden = false;
  lb.dataset.index = String(index);
  document.body.style.overflow = "hidden";
}

function closeLightbox() {
  stopMedia();
  $("#lightbox").hidden = true;
  document.body.style.overflow = "";
}

function clearItems() {
  stopMedia();
  for (const it of state.items) {
    if (it.fullUrl) URL.revokeObjectURL(it.fullUrl);
    if (it.playUrl) URL.revokeObjectURL(it.playUrl);
    if (it.thumbUrl && String(it.thumbUrl).startsWith("blob:")) {
      URL.revokeObjectURL(it.thumbUrl);
    }
  }
  state.items = [];
  state.errors = [];
  state.label = "";
  renderGrid();
}

/**
 * Decode one Unity bundle into image / audio / video items.
 * @returns {{ items: object[], error?: string }}
 */
async function extractAssetsFromBytes(bytes, sourceName) {
  if (!looksLikeUnityBundle(bytes)) {
    return { items: [], error: "UnityFS / UnityWeb / UnityRaw 形式ではありません" };
  }
  let env;
  try {
    env = load(normalizeBundleBytes(bytes));
  } catch (e) {
    return { items: [], error: e.message || String(e) };
  }

  const images = [];
  const audios = [];
  const videos = [];
  for (const asset of env.assets()) {
    if (isImage(asset)) images.push(asset);
    else if (asset.type === "AudioClip") audios.push(asset);
    else if (asset.type === "VideoClip") videos.push(asset);
    else if (asset.type === "MovieTexture" && asset.data?.movieData?.length) {
      videos.push(asset);
    }
  }

  const seen = new Set();
  const uniqueImages = [];
  for (const a of images) {
    const info = imageInfo(a);
    const key = `${a.type}:${info.name}:${info.pathId}`;
    if (!seen.has(key)) {
      seen.add(key);
      uniqueImages.push(a);
    }
  }

  const textures = uniqueImages.filter((a) => a.type === "Texture2D");
  const sprites = uniqueImages.filter((a) => a.type === "Sprite");
  const texNames = new Set(
    textures.map((a) => {
      const i = imageInfo(a);
      return `${i.name}|${i.width}x${i.height}`;
    })
  );
  const finalImages = [
    ...textures,
    ...sprites.filter((a) => {
      const i = imageInfo(a);
      return !texNames.has(`${i.name}|${i.width}x${i.height}`);
    }),
  ];

  if (!finalImages.length && !audios.length && !videos.length) {
    return {
      items: [],
      error: "画像・音声・動画アセットが見つかりませんでした",
    };
  }

  const items = [];

  for (let i = 0; i < finalImages.length; i++) {
    const asset = finalImages[i];
    await yieldToUi();
    try {
      const info = imageInfo(asset);
      const decoded = await decodeImage(asset);
      const pngBytes = encodePng({
        data: decoded.rgba,
        width: decoded.width,
        height: decoded.height,
      });
      const thumbUrl = await makeThumb(decoded.rgba, decoded.width, decoded.height, 360);
      decoded.rgba = null;
      const pngBlob = new Blob([pngBytes], { type: "image/png" });
      const fullUrl = URL.createObjectURL(pngBlob);
      items.push({
        kind: "image",
        sourceName,
        name: info.name || asset.name || `image_${i}`,
        type: asset.type,
        width: decoded.width,
        height: decoded.height,
        formatName: info.formatName || String(info.format),
        pngBytes,
        thumbUrl,
        fullUrl,
        downloadExt: "png",
      });
    } catch (e) {
      state.errors.push({
        sourceName: `${sourceName} / ${asset.name || "image"}`,
        message: e.message || String(e),
      });
    }
  }

  for (let i = 0; i < audios.length; i++) {
    const asset = audios[i];
    await yieldToUi();
    try {
      const data = asset.data;
      const decoded = await decodeAudioClipData(data.audioData, {
        length: data.length,
        channels: data.channels,
        frequency: data.frequency,
        compressionFormat: data.compressionFormat,
        name: data.name || asset.name,
      });
      const playBlob = new Blob([decoded.playBytes], { type: decoded.playMime });
      const playUrl = URL.createObjectURL(playBlob);
      items.push({
        kind: "audio",
        sourceName,
        name: data.name || asset.name || `audio_${i}`,
        type: "AudioClip",
        codecName: decoded.codecName,
        duration: decoded.duration,
        channels: decoded.channels,
        frequency: decoded.frequency,
        playUrl,
        playBytes: decoded.playBytes,
        playMime: decoded.playMime,
        downloadBytes: decoded.downloadBytes,
        downloadExt: decoded.downloadExt,
        downloadMime: decoded.downloadMime,
        oggBytes: decoded.oggBytes || null,
      });
    } catch (e) {
      state.errors.push({
        sourceName: `${sourceName} / ${asset.name || "AudioClip"}`,
        message: e.message || String(e),
      });
    }
  }

  for (let i = 0; i < videos.length; i++) {
    const asset = videos[i];
    await yieldToUi();
    try {
      if (asset.type === "MovieTexture") {
        const data = asset.data;
        const prepared = prepareVideoClipData(data.movieData, {
          originalPath: (asset.name || "movie") + ".ogv",
        });
        const blob = new Blob([prepared.bytes], { type: prepared.mime });
        const playUrl = URL.createObjectURL(blob);
        items.push({
          kind: "video",
          sourceName,
          name: data.name || asset.name || `movie_${i}`,
          type: "MovieTexture",
          width: undefined,
          height: undefined,
          duration: prepared.duration,
          containerLabel: prepared.label,
          ext: prepared.ext,
          playable: prepared.playable,
          unplayableReason: prepared.unplayableReason,
          playUrl,
          bytes: prepared.bytes,
          mime: prepared.mime,
        });
      } else {
        const data = asset.data;
        const prepared = prepareVideoClipData(data.videoData, {
          width: data.width,
          height: data.height,
          frameRate: data.frameRate,
          frameCount: data.frameCount,
          originalPath: data.originalPath,
        });
        const blob = new Blob([prepared.bytes], { type: prepared.mime });
        const playUrl = URL.createObjectURL(blob);
        items.push({
          kind: "video",
          sourceName,
          name: data.name || asset.name || basename(data.originalPath) || `video_${i}`,
          type: "VideoClip",
          width: prepared.width,
          height: prepared.height,
          duration: prepared.duration,
          containerLabel: prepared.label,
          ext: prepared.ext,
          playable: prepared.playable,
          unplayableReason: prepared.unplayableReason,
          playUrl,
          bytes: prepared.bytes,
          mime: prepared.mime,
        });
      }
    } catch (e) {
      state.errors.push({
        sourceName: `${sourceName} / ${asset.name || "VideoClip"}`,
        message: e.message || String(e),
      });
    }
  }

  return { items };
}

async function makeThumb(rgba, w, h, maxSide) {
  const scale = Math.min(1, maxSide / Math.max(w, h));
  const tw = Math.max(1, Math.round(w * scale));
  const th = Math.max(1, Math.round(h * scale));
  const canvas = document.createElement("canvas");
  canvas.width = tw;
  canvas.height = th;
  const ctx = canvas.getContext("2d");
  const full = document.createElement("canvas");
  full.width = w;
  full.height = h;
  full.getContext("2d").putImageData(new ImageData(new Uint8ClampedArray(rgba), w, h), 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(full, 0, 0, tw, th);
  return new Promise((resolve) => {
    canvas.toBlob(
      (blob) => {
        if (blob) resolve(URL.createObjectURL(blob));
        else resolve(canvas.toDataURL("image/jpeg", 0.85));
      },
      "image/jpeg",
      0.85
    );
  });
}

async function expandInputs(files) {
  /** @type {{ name: string, getBytes: () => Promise<Uint8Array> }[]} */
  const units = [];
  for (const file of files) {
    const name = file.webkitRelativePath || file.name;
    const lower = name.toLowerCase();
    if (lower.endsWith(".zip")) {
      const buf = new Uint8Array(await file.arrayBuffer());
      if (!isZipBytes(buf)) {
        units.push({ name, getBytes: async () => buf });
        continue;
      }
      let entries;
      try {
        entries = unzipSync(buf);
      } catch (e) {
        units.push({
          name,
          getBytes: async () => {
            throw new Error(`ZIP を展開できません: ${e.message || e}`);
          },
        });
        continue;
      }
      const zipStem = stem(basename(name));
      for (const [entryName, data] of Object.entries(entries)) {
        if (entryName.endsWith("/")) continue;
        const base = basename(entryName);
        if (!base || base.startsWith(".")) continue;
        const entryData = data;
        units.push({
          name: `${zipStem}/${entryName}`,
          getBytes: async () => entryData,
        });
      }
    } else {
      units.push({
        name: basename(name) || name,
        getBytes: async () => new Uint8Array(await file.arrayBuffer()),
      });
    }
  }
  return units;
}

async function processFiles(fileList) {
  if (!state.ready) {
    setStatus("初期化中です。少し待ってから再度お試しください。", "err");
    return;
  }
  if (state.busy) return;
  const files = Array.from(fileList || []).filter(Boolean);
  if (!files.length) return;

  state.busy = true;
  clearItems();
  state.label = files.length === 1 ? files[0].name : `${files.length} 件の入力`;
  $("#file-label").textContent = state.label;

  try {
    showProgress(true, "入力を準備しています…");
    const units = await expandInputs(files);
    if (!units.length) {
      setStatus("処理対象のファイルがありません", "err");
      return;
    }

    let okFiles = 0;
    let imageCount = 0;
    let audioCount = 0;
    let videoCount = 0;

    for (let i = 0; i < units.length; i++) {
      const unit = units[i];
      showProgress(true, `${i + 1} / ${units.length} 件処理中: ${unit.name}`);
      await yieldToUi();

      let bytes;
      try {
        bytes = await unit.getBytes();
      } catch (e) {
        state.errors.push({ sourceName: unit.name, message: e.message || String(e) });
        continue;
      }

      try {
        const { items, error } = await extractAssetsFromBytes(
          bytes,
          basename(unit.name) || unit.name
        );
        bytes = null;
        if (error && !items.length) {
          state.errors.push({ sourceName: unit.name, message: error });
        } else {
          if (items.length) okFiles++;
          else if (error) state.errors.push({ sourceName: unit.name, message: error });
          for (const it of items) {
            if (it.kind === "image") imageCount++;
            else if (it.kind === "audio") audioCount++;
            else if (it.kind === "video") videoCount++;
          }
          state.items.push(...items);
          renderGrid();
        }
      } catch (e) {
        console.error(e);
        state.errors.push({ sourceName: unit.name, message: e.message || String(e) });
      }
    }

    renderGrid();
    const parts = [];
    const found = [];
    if (imageCount) found.push(`画像 ${imageCount}`);
    if (audioCount) found.push(`音声 ${audioCount}`);
    if (videoCount) found.push(`動画 ${videoCount}`);
    if (found.length) parts.push(`${okFiles} ファイルから ${found.join(" · ")}`);
    else parts.push(`${okFiles} ファイル（メディアなし）`);
    if (state.errors.length) parts.push(`エラー ${state.errors.length} 件`);
    const any = imageCount + audioCount + videoCount;
    setStatus(parts.join(" · "), state.errors.length && !any ? "err" : "ok");
  } catch (e) {
    console.error(e);
    setStatus(`エラー: ${e.message || e}`, "err");
  } finally {
    showProgress(false);
    state.busy = false;
  }
}

function downloadOne(index) {
  const item = state.items[index];
  if (!item) return;
  if (item.kind === "image") {
    downloadBlob(
      new Blob([item.pngBytes], { type: "image/png" }),
      `${safeFilename(item.name)}.png`
    );
    return;
  }
  if (item.kind === "audio") {
    downloadBlob(
      new Blob([item.downloadBytes], { type: item.downloadMime || "application/octet-stream" }),
      `${safeFilename(item.name)}.${item.downloadExt || "wav"}`
    );
    return;
  }
  downloadBlob(
    new Blob([item.bytes], { type: item.mime || "application/octet-stream" }),
    `${safeFilename(item.name)}.${item.ext || "bin"}`
  );
}

function downloadAllZip() {
  if (!state.items.length) return;
  const files = {};
  const used = new Set();
  for (const item of state.items) {
    const folder = safeFilename(stem(item.sourceName) || "export");
    let base = safeFilename(item.name);
    let ext = "png";
    let bytes = item.pngBytes;
    if (item.kind === "audio") {
      ext = item.downloadExt || "wav";
      bytes = item.downloadBytes;
    } else if (item.kind === "video") {
      ext = item.ext || "bin";
      bytes = item.bytes;
    }
    let path = `${folder}/${base}.${ext}`;
    let n = 2;
    while (used.has(path)) {
      path = `${folder}/${base}_${n}.${ext}`;
      n++;
    }
    used.add(path);
    files[path] = bytes;
  }
  const zipped = zipSync(files, { level: 6 });
  const zipName =
    safeFilename(stem(state.label) || `export_${state.items.length}`) + "_export.zip";
  downloadBlob(new Blob([zipped], { type: "application/zip" }), zipName);
}

async function collectDroppedFiles(dataTransfer) {
  const out = [];
  const items = dataTransfer?.items;
  if (items && items.length) {
    const entries = [];
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item.kind !== "file") continue;
      if (typeof item.getAsFileSystemHandle === "function") {
        try {
          const handle = await item.getAsFileSystemHandle();
          if (handle) {
            await walkHandle(handle, "", out);
            continue;
          }
        } catch {
          /* fall through */
        }
      }
      const entry = item.webkitGetAsEntry?.();
      if (entry) {
        entries.push(entry);
        continue;
      }
      const f = item.getAsFile?.();
      if (f) out.push(f);
    }
    for (const entry of entries) {
      await walkEntry(entry, out);
    }
    if (out.length) return out;
  }
  return Array.from(dataTransfer?.files || []);
}

async function walkHandle(handle, pathPrefix, out) {
  if (handle.kind === "file") {
    const file = await handle.getFile();
    const name = pathPrefix ? `${pathPrefix}/${file.name}` : file.name;
    Object.defineProperty(file, "webkitRelativePath", { value: name });
    out.push(file);
    return;
  }
  if (handle.kind === "directory") {
    const prefix = pathPrefix ? `${pathPrefix}/${handle.name}` : handle.name;
    for await (const entry of handle.values()) {
      await walkHandle(entry, prefix, out);
    }
  }
}

function walkEntry(entry, out) {
  return new Promise((resolve, reject) => {
    if (entry.isFile) {
      entry.file(
        (file) => {
          Object.defineProperty(file, "webkitRelativePath", {
            value: entry.fullPath?.replace(/^\//, "") || file.name,
          });
          out.push(file);
          resolve();
        },
        reject
      );
    } else if (entry.isDirectory) {
      const reader = entry.createReader();
      const readBatch = () => {
        reader.readEntries(async (results) => {
          if (!results.length) {
            resolve();
            return;
          }
          try {
            for (const child of results) {
              await walkEntry(child, out);
            }
            readBatch();
          } catch (e) {
            reject(e);
          }
        }, reject);
      };
      readBatch();
    } else {
      resolve();
    }
  });
}

function supportsDirectoryPicker() {
  const input = document.createElement("input");
  input.type = "file";
  const supported = "webkitdirectory" in input;
  const ua = navigator.userAgent || "";
  const isMobile = /iPhone|iPad|iPod|Android/i.test(ua);
  return supported && !isMobile;
}

async function init() {
  setStatus("デコーダを読み込み中…");
  try {
    await initTexture({ wasmPath: WASM_PATH });
    await initMedia();
    state.ready = true;
    setStatus("アセットバンドルやフォルダ、ZIP を選んでください（画像・音声・動画）");
  } catch (e) {
    console.error(e);
    setStatus(`初期化に失敗しました: ${e.message || e}`, "err");
  }
}

function setupUI() {
  const input = $("#file");
  const folderInput = $("#folder");
  const drop = $("#drop");

  input.multiple = true;

  $("#pick-btn").addEventListener("click", () => input.click());
  input.addEventListener("change", () => {
    const list = input.files;
    if (list?.length) processFiles(list);
    input.value = "";
  });

  const folderSupported = supportsDirectoryPicker();
  const folderBtn = $("#folder-btn");
  const folderHint = $("#folder-hint");
  if (folderSupported) {
    folderBtn.hidden = false;
    folderHint.hidden = true;
    folderBtn.addEventListener("click", () => folderInput.click());
    folderInput.addEventListener("change", () => {
      const list = folderInput.files;
      if (list?.length) processFiles(list);
      folderInput.value = "";
    });
  } else {
    folderBtn.hidden = true;
    folderHint.hidden = false;
  }

  drop.addEventListener("dragover", (e) => {
    e.preventDefault();
    drop.classList.add("drag");
  });
  drop.addEventListener("dragleave", () => drop.classList.remove("drag"));
  drop.addEventListener("drop", async (e) => {
    e.preventDefault();
    drop.classList.remove("drag");
    try {
      const files = await collectDroppedFiles(e.dataTransfer);
      if (files.length) processFiles(files);
    } catch (err) {
      console.error(err);
      setStatus(`ドロップの読み取りに失敗: ${err.message || err}`, "err");
    }
  });

  $("#btn-zip").addEventListener("click", downloadAllZip);
  $("#btn-clear").addEventListener("click", () => {
    clearItems();
    $("#file-label").textContent = "ファイル未選択";
    setStatus("アセットバンドルやフォルダ、ZIP を選んでください（画像・音声・動画）");
  });

  $("#lb-close").addEventListener("click", closeLightbox);
  $("#lb-backdrop").addEventListener("click", closeLightbox);
  $("#lb-download").addEventListener("click", () => {
    const i = Number($("#lightbox").dataset.index);
    downloadOne(i);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeLightbox();
  });

  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("./sw.js").catch(() => {});
  }
}

setupUI();
init();
